/* SPDX-License-Identifier: Apache-2.0
 *
 * Zephyr RTOS ADC example for nrf52840dk/nrf52840
 * Reads a single ADC channel, converts the raw value to millivolts,
 * and prints the result once per second.
 */

#include <zephyr/kernel.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/devicetree.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(adc_example, LOG_LEVEL_INF);

/* Get the ADC DT spec from the node /zephyr,user (defined in an overlay) */
static const struct adc_dt_spec adc_spec = ADC_DT_SPEC_GET(DT_PATH(zephyr_user));

int main(void)
{
    int ret;

    if (!device_is_ready(adc_spec.dev)) {
        LOG_ERR("ADC device not ready");
        return 0;
    }

    /* Configure the ADC channel described by the DT node */
    ret = adc_channel_setup_dt(&adc_spec);
    if (ret) {
        LOG_ERR("Failed to setup ADC channel (err %d)", ret);
        return 0;
    }

    while (1) {
        int16_t sample_buf;          /* Sample buffer */
        int32_t millivolts;          /* Converted value */

        /* Perform a single conversion */
        ret = adc_read_dt(&adc_spec, &sample_buf);
        if (ret) {
            LOG_ERR("ADC read error (%d)", ret);
        } else {
            /* Convert raw reading to millivolts */
            millivolts = adc_raw_to_millivolts_dt(&adc_spec,
                                                  (int32_t)sample_buf);
            printk("ADC reading: %d mV\n", millivolts);
        }

        k_sleep(K_MSEC(1000));
    }

    /* Unreachable */
    return 0;
}
